/// Rolling checksum used by the transfer protocol.
pub fn compute_checksum(data: &[u8]) -> u32 {
    let mut a: u32 = 1;
    let mut b: u32 = 0;
    for byte in data {
        a = (a + u32::from(*byte)) % 65521;
        b = (b + a) % 65521;
    }
    (b << 16) | a
}

pub fn unrelated_helper() -> u32 {
    42
}
